package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log"
	"mime"
	"net/http"
	"strings"
	"sync"
	"time"
	"unicode/utf8"
)

const (
	maxTitleLen  = 200
	maxBodyBytes = 1 << 20
)

type Todo struct {
	ID    int    `json:"id"`
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

// createTodoRequest is the accepted POST /todos body. It is separate from
// Todo so that clients cannot set id.
type createTodoRequest struct {
	Title string `json:"title"`
	Done  bool   `json:"done"`
}

type store struct {
	mu    sync.Mutex
	next  int
	todos []Todo
}

type apiError struct {
	Code    string `json:"code"`
	Message string `json:"message"`
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]apiError{"error": {Code: code, Message: msg}})
}

func (s *store) list(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	json.NewEncoder(w).Encode(s.todos)
}

func (s *store) create(w http.ResponseWriter, r *http.Request) {
	mt, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mt != "application/json" {
		writeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type", "Content-Type must be application/json")
		return
	}

	req, status, code, msg := decodeCreate(w, r)
	if status != 0 {
		writeError(w, status, code, msg)
		return
	}

	title := strings.TrimSpace(req.Title)
	switch {
	case title == "":
		writeError(w, http.StatusBadRequest, "validation_failed", "title is required")
		return
	case !utf8.ValidString(title):
		writeError(w, http.StatusBadRequest, "validation_failed", "title must be valid UTF-8")
		return
	case utf8.RuneCountInString(title) > maxTitleLen:
		writeError(w, http.StatusBadRequest, "validation_failed", fmt.Sprintf("title must be at most %d characters", maxTitleLen))
		return
	}

	t := Todo{Title: title, Done: req.Done}
	s.mu.Lock()
	s.next++
	t.ID = s.next
	s.todos = append(s.todos, t)
	s.mu.Unlock()
	writeJSON(w, http.StatusCreated, t)
}

// decodeCreate reads exactly one JSON object with only known fields. On
// failure it returns a non-zero status with an error code and message.
func decodeCreate(w http.ResponseWriter, r *http.Request) (req createTodoRequest, status int, code, msg string) {
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	dec.DisallowUnknownFields()

	err := dec.Decode(&req)
	if err == nil {
		if dec.Decode(&struct{}{}) != io.EOF {
			return req, http.StatusBadRequest, "invalid_json", "body must contain a single JSON object"
		}
		return req, 0, "", ""
	}

	var syntaxErr *json.SyntaxError
	var typeErr *json.UnmarshalTypeError
	var maxErr *http.MaxBytesError
	switch {
	case errors.As(err, &maxErr):
		return req, http.StatusRequestEntityTooLarge, "body_too_large", fmt.Sprintf("body must be at most %d bytes", maxBodyBytes)
	case errors.Is(err, io.EOF):
		return req, http.StatusBadRequest, "invalid_json", "body must not be empty"
	case errors.As(err, &syntaxErr), errors.Is(err, io.ErrUnexpectedEOF):
		return req, http.StatusBadRequest, "invalid_json", "body is not valid JSON"
	case errors.As(err, &typeErr):
		if typeErr.Field == "" {
			return req, http.StatusBadRequest, "invalid_json", "body must be a JSON object"
		}
		return req, http.StatusBadRequest, "validation_failed", fmt.Sprintf("field %q must be a %s", typeErr.Field, typeErr.Type)
	case strings.HasPrefix(err.Error(), "json: unknown field "):
		field := strings.TrimPrefix(err.Error(), "json: unknown field ")
		return req, http.StatusBadRequest, "unknown_field", "unknown field " + field
	default:
		return req, http.StatusBadRequest, "invalid_json", "body is not valid JSON"
	}
}

func newServer(s *store, limiter *rateLimiter) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /todos", s.list)
	mux.HandleFunc("POST /todos", limiter.middleware(s.create))
	return mux
}

func main() {
	limiter := newRateLimiter(5, 10, 5*time.Minute, nil)
	log.Fatal(http.ListenAndServe(":8080", newServer(&store{}, limiter)))
}

package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
	"time"
)

type fakeClock struct{ t time.Time }

func (c *fakeClock) now() time.Time          { return c.t }
func (c *fakeClock) advance(d time.Duration) { c.t = c.t.Add(d) }

func newTestServer() (http.Handler, *fakeClock) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	return newServer(&store{}, newRateLimiter(5, 10, 5*time.Minute, clk.now)), clk
}

func postTodo(h http.Handler, ip, contentType, body string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(http.MethodPost, "/todos", strings.NewReader(body))
	req.RemoteAddr = ip + ":1234"
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func decodeError(t *testing.T, rec *httptest.ResponseRecorder) apiError {
	t.Helper()
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	var body struct {
		Error apiError `json:"error"`
	}
	if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil {
		t.Fatalf("error body is not JSON: %v (%q)", err, rec.Body.String())
	}
	if body.Error.Code == "" || body.Error.Message == "" {
		t.Fatalf("error body missing code/message: %q", rec.Body.String())
	}
	return body.Error
}

func TestCreateTodoSuccess(t *testing.T) {
	h, _ := newTestServer()
	rec := postTodo(h, "10.0.0.1", "application/json; charset=utf-8", `{"title":"  buy milk  ","done":true}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, want 201; body %s", rec.Code, rec.Body)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Errorf("Content-Type = %q", ct)
	}
	var got Todo
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatal(err)
	}
	want := Todo{ID: 1, Title: "buy milk", Done: true}
	if got != want {
		t.Errorf("got %+v, want %+v", got, want)
	}
}

func TestCreateTodoTitleAtLimit(t *testing.T) {
	h, _ := newTestServer()
	// 200 multi-byte runes is valid: the limit is in characters, not bytes.
	title := strings.Repeat("é", maxTitleLen)
	rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"`+title+`"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("status = %d, want 201; body %s", rec.Code, rec.Body)
	}
}

func TestCreateTodoRejectsBadInput(t *testing.T) {
	tests := []struct {
		name        string
		contentType string
		body        string
		status      int
		code        string
	}{
		{"missing title", "application/json", `{"done":true}`, 400, "validation_failed"},
		{"empty title", "application/json", `{"title":""}`, 400, "validation_failed"},
		{"blank title", "application/json", `{"title":"   "}`, 400, "validation_failed"},
		{"null title", "application/json", `{"title":null}`, 400, "validation_failed"},
		{"title too long", "application/json", `{"title":"` + strings.Repeat("a", maxTitleLen+1) + `"}`, 400, "validation_failed"},
		{"title wrong type", "application/json", `{"title":123}`, 400, "validation_failed"},
		{"done wrong type", "application/json", `{"title":"x","done":"yes"}`, 400, "validation_failed"},
		{"unknown field", "application/json", `{"title":"x","priority":1}`, 400, "unknown_field"},
		{"client-supplied id", "application/json", `{"id":99,"title":"x"}`, 400, "unknown_field"},
		{"empty body", "application/json", ``, 400, "invalid_json"},
		{"malformed json", "application/json", `{"title":`, 400, "invalid_json"},
		{"syntax error", "application/json", `{"title" "x"}`, 400, "invalid_json"},
		{"array body", "application/json", `[{"title":"x"}]`, 400, "invalid_json"},
		{"trailing data", "application/json", `{"title":"x"}{"title":"y"}`, 400, "invalid_json"},
		{"body too large", "application/json", `{"title":"` + strings.Repeat("a", maxBodyBytes) + `"}`, 413, "body_too_large"},
		{"missing content type", "", `{"title":"x"}`, 415, "unsupported_media_type"},
		{"wrong content type", "text/plain", `{"title":"x"}`, 415, "unsupported_media_type"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			h, _ := newTestServer()
			rec := postTodo(h, "10.0.0.1", tc.contentType, tc.body)
			if rec.Code != tc.status {
				t.Fatalf("status = %d, want %d; body %s", rec.Code, tc.status, rec.Body)
			}
			if e := decodeError(t, rec); e.Code != tc.code {
				t.Errorf("code = %q, want %q (message %q)", e.Code, tc.code, e.Message)
			}
		})
	}
}

func TestRejectedTodoIsNotStored(t *testing.T) {
	h, _ := newTestServer()
	postTodo(h, "10.0.0.1", "application/json", `{"title":""}`)
	rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"ok"}`)
	var got Todo
	json.Unmarshal(rec.Body.Bytes(), &got)
	if got.ID != 1 {
		t.Errorf("ID = %d, want 1 (rejected request must not consume an ID)", got.ID)
	}
}

func TestCreateTodoRateLimited(t *testing.T) {
	h, clk := newTestServer()
	for i := range 10 {
		if rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"x"}`); rec.Code != http.StatusCreated {
			t.Fatalf("request %d: status = %d, want 201", i+1, rec.Code)
		}
	}

	rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"x"}`)
	if rec.Code != http.StatusTooManyRequests {
		t.Fatalf("status = %d, want 429", rec.Code)
	}
	if ra := rec.Header().Get("Retry-After"); ra != "1" {
		t.Errorf("Retry-After = %q, want 1", ra)
	}
	if e := decodeError(t, rec); e.Code != "rate_limited" {
		t.Errorf("code = %q, want rate_limited", e.Code)
	}

	// Another client is unaffected.
	if rec := postTodo(h, "10.0.0.2", "application/json", `{"title":"x"}`); rec.Code != http.StatusCreated {
		t.Errorf("other client: status = %d, want 201", rec.Code)
	}

	// At 5 tokens/s, one token is back after 200ms.
	clk.advance(200 * time.Millisecond)
	if rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"x"}`); rec.Code != http.StatusCreated {
		t.Errorf("after refill: status = %d, want 201", rec.Code)
	}
	if rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"x"}`); rec.Code != http.StatusTooManyRequests {
		t.Errorf("after one refill token: status = %d, want 429", rec.Code)
	}
}

func TestInvalidRequestsCountTowardRateLimit(t *testing.T) {
	h, _ := newTestServer()
	for range 10 {
		postTodo(h, "10.0.0.1", "application/json", `garbage`)
	}
	if rec := postTodo(h, "10.0.0.1", "application/json", `{"title":"x"}`); rec.Code != http.StatusTooManyRequests {
		t.Errorf("status = %d, want 429", rec.Code)
	}
}

package main

import (
	"net/http/httptest"
	"testing"
	"time"
)

func TestRateLimiterBurstCappedAfterIdle(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	l := newRateLimiter(5, 3, time.Hour, clk.now)
	for range 3 {
		l.allow("a")
	}
	clk.advance(10 * time.Minute)
	for i := range 3 {
		if ok, _ := l.allow("a"); !ok {
			t.Fatalf("request %d after idle denied", i+1)
		}
	}
	if ok, wait := l.allow("a"); ok || wait != 200*time.Millisecond {
		t.Errorf("allow = %v, %v; want false, 200ms (tokens must not exceed burst)", ok, wait)
	}
}

func TestRateLimiterEvictsIdleBuckets(t *testing.T) {
	clk := &fakeClock{t: time.Unix(0, 0)}
	l := newRateLimiter(5, 10, time.Minute, clk.now)
	l.allow("a")
	l.allow("b")
	clk.advance(30 * time.Second)
	l.allow("b")
	clk.advance(31 * time.Second)
	l.allow("c") // triggers a sweep: a is idle 61s, b only 31s

	if _, ok := l.buckets["a"]; ok {
		t.Error("idle bucket a was not evicted")
	}
	if _, ok := l.buckets["b"]; !ok {
		t.Error("recently used bucket b was evicted")
	}
	if len(l.buckets) != 2 {
		t.Errorf("len(buckets) = %d, want 2", len(l.buckets))
	}
}

func TestClientIP(t *testing.T) {
	tests := []struct{ remote, xff, want string }{
		{"192.0.2.1:5555", "", "192.0.2.1"},
		{"[2001:db8::1]:5555", "", "2001:db8::1"},
		{"192.0.2.1:5555", "203.0.113.9", "192.0.2.1"}, // spoofable header ignored
		{"no-port", "", "no-port"},
	}
	for _, tc := range tests {
		r := httptest.NewRequest("POST", "/todos", nil)
		r.RemoteAddr = tc.remote
		if tc.xff != "" {
			r.Header.Set("X-Forwarded-For", tc.xff)
		}
		if got := clientIP(r); got != tc.want {
			t.Errorf("clientIP(%q) = %q, want %q", tc.remote, got, tc.want)
		}
	}
}

